window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["elevenlabs"]={html:"<div class=\"own-elevenlabs\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────────── -->\n  <header class=\"el-nav\" id=\"elNav\">\n    <a class=\"el-wordmark\" href=\"#el-top\" aria-label=\"Northwind home\">Northwind</a>\n    <nav class=\"el-menu\" aria-label=\"Primary\">\n      <a href=\"#el-hero\">Product</a>\n      <a href=\"#el-library\">Operations</a>\n      <a href=\"#el-wave\">Platform</a>\n      <a href=\"#el-pricing\">Pricing</a>\n      <a href=\"#el-voices\">Customers</a>\n    </nav>\n    <div class=\"el-nav-right\">\n      <a class=\"el-nav-link\" href=\"#\">Sign in</a>\n      <a class=\"el-btn el-btn-primary\" href=\"#el-pricing\">Try free</a>\n      <button class=\"el-burger\" type=\"button\" id=\"elBurger\" aria-label=\"Open menu\" aria-expanded=\"false\"><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"el-top\">\n    <!-- ── HERO with atmospheric gradient orb ─────────────────────────────── -->\n    <section id=\"el-hero\" class=\"el-hero\" aria-labelledby=\"elHeroH\">\n      <div class=\"el-orb el-orb-mint\" aria-hidden=\"true\"></div>\n      <div class=\"el-orb el-orb-peach\" aria-hidden=\"true\"></div>\n      <div class=\"el-orb el-orb-lavender\" aria-hidden=\"true\"></div>\n      <p class=\"el-eyebrow\">Operations intelligence</p>\n      <h1 id=\"elHeroH\" class=\"el-hero-title\">The operations story,<br>told in one clear voice</h1>\n      <p class=\"el-hero-sub\">Northwind turns the noise of the floor into a single reconciled narrative &mdash; read the same way by the analyst, the line lead, and the night shift.</p>\n      <div class=\"el-hero-cta\">\n        <a class=\"el-btn el-btn-primary el-btn-lg\" href=\"#el-pricing\">Try Northwind free</a>\n        <a class=\"el-btn el-btn-outline el-btn-lg\" href=\"#el-wave\">Hear a digest</a>\n      </div>\n\n      <!-- audio waveform card -->\n      <div id=\"el-wave\" class=\"el-wave\" aria-label=\"Shift digest playback\">\n        <button class=\"el-wave-play\" type=\"button\" id=\"elPlay\" aria-label=\"Play shift digest\">\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M8 5v14l11-7z\" fill=\"currentColor\"/></svg>\n        </button>\n        <div class=\"el-wave-mid\">\n          <span class=\"el-wave-title\">Shift digest &mdash; Line 04, week 41</span>\n          <div class=\"el-bars\" id=\"elBars\" aria-hidden=\"true\"></div>\n        </div>\n        <span class=\"el-wave-time\" id=\"elTime\">0:18</span>\n      </div>\n    </section>\n\n    <!-- ── GRADIENT ORB FEATURE CARDS ──────────────────────────────────────── -->\n    <section class=\"el-orbcards\" aria-labelledby=\"elOrbH\">\n      <div class=\"el-orbcards-head\">\n        <h2 id=\"elOrbH\" class=\"el-h2\">One governed model, every surface</h2>\n        <p class=\"el-lead\">Calm, editorial, and consistent &mdash; from the board on the wall to the digest in a pocket.</p>\n      </div>\n      <div class=\"el-orb-grid\" id=\"elOrbGrid\"></div>\n    </section>\n\n    <!-- ── VOICE LIBRARY (rule-separated rows) ─────────────────────────────── -->\n    <section id=\"el-library\" class=\"el-library\" aria-labelledby=\"elLibH\">\n      <div class=\"el-library-head\">\n        <div>\n          <h2 id=\"elLibH\" class=\"el-h2\">The board library</h2>\n          <p class=\"el-lead\">Every governed surface, ready to read, share, or schedule.</p>\n        </div>\n        <label class=\"el-search\">\n          <span class=\"el-sr\">Search boards</span>\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m20 20-4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>\n          <input type=\"search\" placeholder=\"Search boards\" autocomplete=\"off\">\n        </label>\n      </div>\n      <ul class=\"el-voice-list\" id=\"elVoiceList\"></ul>\n    </section>\n\n    <!-- ── PRODUCT STACK ───────────────────────────────────────────────────── -->\n    <section class=\"el-stack-sec\" aria-labelledby=\"elStackH\">\n      <div class=\"el-stack-copy\">\n        <p class=\"el-eyebrow\">The platform</p>\n        <h2 id=\"elStackH\" class=\"el-h2\">Editorial pacing for operational data</h2>\n        <p class=\"el-lead\">A semantic layer that reads like a magazine and audits like a ledger. Definitions held once, surfaced everywhere.</p>\n        <a class=\"el-link\" href=\"#el-pricing\">Explore the platform <span aria-hidden=\"true\">&rarr;</span></a>\n      </div>\n      <div class=\"el-stack\" aria-hidden=\"true\">\n        <div class=\"el-stack-card el-stack-a\"><span class=\"el-stack-k\">Line 04</span><span class=\"el-stack-v\">98.4%</span></div>\n        <div class=\"el-stack-card el-stack-b\"><span class=\"el-stack-k\">Line 09</span><span class=\"el-stack-v\">94.6%</span></div>\n        <div class=\"el-stack-card el-stack-c\"><span class=\"el-stack-k\">Line 07</span><span class=\"el-stack-v\">92.8%</span></div>\n      </div>\n    </section>\n\n    <!-- ── TESTIMONIALS ────────────────────────────────────────────────────── -->\n    <section id=\"el-voices\" class=\"el-quotes\" aria-labelledby=\"elQuotesH\">\n      <div class=\"el-quotes-head\">\n        <h2 id=\"elQuotesH\" class=\"el-h2\">Trusted on the floor</h2>\n      </div>\n      <div class=\"el-quote-grid\" id=\"elQuoteGrid\"></div>\n    </section>\n\n    <!-- ── PRICING ──────────────────────────────────────────────────────────── -->\n    <section id=\"el-pricing\" class=\"el-pricing\" aria-labelledby=\"elPricingH\">\n      <div class=\"el-pricing-head\">\n        <h2 id=\"elPricingH\" class=\"el-h2\">Simple pricing, calmly stated</h2>\n        <p class=\"el-lead\">Start free. Add regions and seats when the operation grows.</p>\n      </div>\n      <div class=\"el-tier-grid\">\n        <article class=\"el-tier\">\n          <span class=\"el-tier-name\">Reader</span>\n          <span class=\"el-tier-price\">Free</span>\n          <ul><li>1 board</li><li>1 seat</li><li>Community support</li></ul>\n          <a class=\"el-btn el-btn-outline\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"el-tier el-tier-featured\">\n          <span class=\"el-tier-name\">Operations</span>\n          <span class=\"el-tier-price\">$90<span>/seat/mo</span></span>\n          <ul><li>Unlimited boards</li><li>Scheduled digests</li><li>Reconciliation engine</li></ul>\n          <a class=\"el-btn el-btn-primary\" href=\"#\">Start free trial</a>\n        </article>\n        <article class=\"el-tier\">\n          <span class=\"el-tier-name\">Enterprise</span>\n          <span class=\"el-tier-price\">Custom</span>\n          <ul><li>SSO &amp; audit</li><li>Private model</li><li>Dedicated support</li></ul>\n          <a class=\"el-btn el-btn-outline\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── CTA BAND ──────────────────────────────────────────────────────────── -->\n  <section class=\"el-cta\" aria-labelledby=\"elCtaH\">\n    <div class=\"el-orb el-orb-sky el-orb-cta\" aria-hidden=\"true\"></div>\n    <h2 id=\"elCtaH\" class=\"el-cta-title\">Bring the whole operation into one story</h2>\n    <a class=\"el-btn el-btn-primary el-btn-lg\" href=\"#\">Try Northwind free</a>\n  </section>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────────── -->\n  <footer class=\"el-foot\">\n    <div class=\"el-foot-cols\">\n      <div class=\"el-foot-col\"><h3>Product</h3><a href=\"#\">Boards</a><a href=\"#\">Metric model</a><a href=\"#\">Digests</a><a href=\"#\">Integrations</a></div>\n      <div class=\"el-foot-col\"><h3>Solutions</h3><a href=\"#\">Manufacturing</a><a href=\"#\">Logistics</a><a href=\"#\">Financial ops</a><a href=\"#\">Public sector</a></div>\n      <div class=\"el-foot-col\"><h3>Resources</h3><a href=\"#\">Docs</a><a href=\"#\">Blog</a><a href=\"#\">Security</a><a href=\"#\">Changelog</a></div>\n      <div class=\"el-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Newsroom</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"el-legal\">\n      <span>&copy; 2026 Northwind Analytics — a fictional product. Sample data, showcase only.</span>\n      <span class=\"el-legal-right\">Philippines</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in ElevenLabs' design language, for showcase.html ══════════\n   Off-white editorial canvas (#f5f5f5) with warm near-black ink (#0c0a09),\n   Waldenburg Light at weight 300 for display (serif -> Times fallback), Inter\n   for body with subtle positive tracking, ink-pill CTAs, 16-24px cards, and soft\n   pastel gradient orbs (mint / peach / lavender / sky / rose) drifting through\n   hero and CTA bands as pure atmosphere. 96px section rhythm, hairline + soft\n   single shadow tier. */\n\n.own-elevenlabs {\n  --primary: #292524;\n  --primary-active: #0c0a09;\n  --ink: #0c0a09;\n  --body: #4e4e4e;\n  --muted: #777169;\n  --muted-soft: #a8a29e;\n  --hairline: #e7e5e4;\n  --hairline-soft: #f0efed;\n  --hairline-strong: #d6d3d1;\n  --canvas: #f5f5f5;\n  --canvas-soft: #fafafa;\n  --surface-card: #ffffff;\n  --surface-strong: #f0efed;\n  --surface-dark: #0c0a09;\n  --on-primary: #ffffff;\n  --on-dark: #ffffff;\n  --gradient-mint: #a7e5d3;\n  --gradient-peach: #f4c5a8;\n  --gradient-lavender: #c8b8e0;\n  --gradient-sky: #a8c8e8;\n  --gradient-rose: #e8b8c4;\n\n  --font-display: 'Waldenburg', 'EB Garamond', 'Times New Roman', serif;\n  --font-body: 'Inter', sans-serif;\n\n  --r-xs: 4px;\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-xxl: 24px;\n  --r-pill: 9999px;\n\n  --shadow-soft: 0 4px 16px rgba(0, 0, 0, .04);\n\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font-body);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n.own-elevenlabs *, .own-elevenlabs *::before, .own-elevenlabs *::after { box-sizing: border-box; }\n.own-elevenlabs a { color: inherit; text-decoration: none; }\n.own-elevenlabs button { font: inherit; cursor: pointer; }\n.own-elevenlabs :focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; border-radius: 6px; }\n.own-elevenlabs .el-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── nav ───────────────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-nav { position: sticky; top: 68px; z-index: 40; display: flex; align-items: center; gap: 24px; height: 64px; padding: 0 var(--gut); background: rgba(245, 245, 245, .86); border-bottom: 1px solid var(--hairline); backdrop-filter: saturate(180%) blur(12px); -webkit-backdrop-filter: saturate(180%) blur(12px); }\n.own-elevenlabs .el-wordmark { font-family: var(--font-display); font-size: 22px; font-weight: 300; letter-spacing: -0.3px; color: var(--ink); }\n.own-elevenlabs .el-menu { display: flex; gap: 26px; margin: 0 auto; font-size: 15px; font-weight: 500; color: var(--body); }\n.own-elevenlabs .el-menu a:hover { color: var(--ink); }\n.own-elevenlabs .el-nav-right { display: flex; align-items: center; gap: 14px; margin-left: auto; }\n.own-elevenlabs .el-nav-link { font-size: 15px; font-weight: 500; color: var(--body); }\n.own-elevenlabs .el-nav-link:hover { color: var(--ink); }\n.own-elevenlabs .el-burger { display: none; flex-direction: column; gap: 4px; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--hairline-strong); border-radius: var(--r-md); background: var(--surface-card); }\n.own-elevenlabs .el-burger span { display: block; width: 18px; height: 2px; background: var(--ink); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 40px; padding: 0 20px; border: 1px solid transparent; border-radius: var(--r-pill); font-family: var(--font-body); font-size: 15px; font-weight: 500; line-height: 1; transition: background-color .18s, border-color .18s; }\n.own-elevenlabs .el-btn-lg { height: 48px; padding: 0 26px; }\n.own-elevenlabs .el-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-elevenlabs .el-btn-primary:hover { background: var(--primary-active); }\n.own-elevenlabs .el-btn-outline { background: transparent; color: var(--ink); border-color: var(--hairline-strong); }\n.own-elevenlabs .el-btn-outline:hover { border-color: var(--ink); }\n.own-elevenlabs .el-link { display: inline-flex; align-items: center; gap: 8px; font-size: 16px; color: var(--ink); }\n.own-elevenlabs .el-link:hover { text-decoration: underline; text-underline-offset: 3px; }\n\n.own-elevenlabs .el-eyebrow { display: inline-block; margin-bottom: 16px; font-size: 12px; font-weight: 600; letter-spacing: .96px; text-transform: uppercase; color: var(--muted); }\n.own-elevenlabs .el-h2 { font-family: var(--font-display); font-size: clamp(30px, 4.2cqi, 48px); font-weight: 300; line-height: 1.12; letter-spacing: -0.9px; }\n.own-elevenlabs .el-lead { margin-top: 16px; max-width: 52ch; font-size: 16px; line-height: 1.5; letter-spacing: .16px; color: var(--body); }\n\n/* ── gradient orbs (atmosphere only) ──────────────────────────────────────── */\n.own-elevenlabs .el-orb { position: absolute; border-radius: 50%; filter: blur(46px); opacity: .6; pointer-events: none; }\n.own-elevenlabs .el-orb-mint { width: 320px; height: 320px; left: 6%; top: 8%; background: radial-gradient(circle, var(--gradient-mint), transparent 70%); }\n.own-elevenlabs .el-orb-peach { width: 260px; height: 260px; right: 10%; top: 24%; background: radial-gradient(circle, var(--gradient-peach), transparent 70%); }\n.own-elevenlabs .el-orb-lavender { width: 300px; height: 300px; left: 38%; bottom: -60px; background: radial-gradient(circle, var(--gradient-lavender), transparent 70%); }\n.own-elevenlabs .el-orb-sky { background: radial-gradient(circle, var(--gradient-sky), transparent 70%); }\n.own-elevenlabs .el-orb-cta { width: 420px; height: 420px; left: 50%; top: -40%; transform: translateX(-50%); }\n\n/* ── hero ──────────────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-hero { position: relative; padding: var(--section) var(--gut) clamp(40px, 6cqi, 72px); text-align: center; }\n.own-elevenlabs .el-hero-title { position: relative; z-index: 1; font-family: var(--font-display); font-size: clamp(40px, 6.8cqi, 64px); font-weight: 300; line-height: 1.05; letter-spacing: -1.92px; max-width: 18ch; margin: 0 auto; }\n.own-elevenlabs .el-hero-sub { position: relative; z-index: 1; margin: 22px auto 0; max-width: 58ch; font-size: 16px; line-height: 1.5; letter-spacing: .16px; color: var(--body); }\n.own-elevenlabs .el-hero-cta { position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; gap: 12px; flex-wrap: wrap; margin-top: 30px; }\n\n/* ── waveform card ─────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-wave { position: relative; z-index: 1; display: flex; align-items: center; gap: 20px; margin: clamp(36px, 5cqi, 64px) auto 0; width: min(760px, 100%); padding: 24px; border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--surface-card); box-shadow: var(--shadow-soft); text-align: left; }\n.own-elevenlabs .el-wave-play { display: grid; place-items: center; flex: none; width: 52px; height: 52px; border: 0; border-radius: 9999px; background: var(--primary); color: var(--on-primary); }\n.own-elevenlabs .el-wave-play:hover { background: var(--primary-active); }\n.own-elevenlabs .el-wave-play svg { width: 22px; height: 22px; }\n.own-elevenlabs .el-wave-mid { flex: 1; min-width: 0; }\n.own-elevenlabs .el-wave-title { display: block; margin-bottom: 10px; font-size: 15px; font-weight: 500; letter-spacing: .18px; color: var(--ink); }\n.own-elevenlabs .el-bars { display: flex; align-items: center; gap: 3px; height: 40px; }\n.own-elevenlabs .el-bars i { flex: 1; min-width: 2px; border-radius: 2px; background: var(--hairline-strong); height: var(--h, 30%); }\n.own-elevenlabs .el-bars.playing i { background: var(--primary); }\n.own-elevenlabs .el-wave-time { font-size: 14px; color: var(--muted); flex: none; font-variant-numeric: tabular-nums; }\n\n/* ── orb feature cards ─────────────────────────────────────────────────────── */\n.own-elevenlabs .el-orbcards { padding: var(--section) var(--gut); }\n.own-elevenlabs .el-orbcards-head { text-align: center; max-width: 700px; margin: 0 auto clamp(32px, 5cqi, 56px); }\n.own-elevenlabs .el-orb-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-elevenlabs .el-orb-card { position: relative; overflow: hidden; display: grid; gap: 12px; align-content: start; min-height: 240px; padding: 32px; border-radius: var(--r-xxl); background: var(--canvas-soft); border: 1px solid var(--hairline); }\n.own-elevenlabs .el-orb-card .el-card-orb { position: absolute; right: -40px; top: -40px; width: 180px; height: 180px; border-radius: 50%; filter: blur(34px); opacity: .7; pointer-events: none; }\n.own-elevenlabs .el-orb-card h3 { position: relative; z-index: 1; font-family: var(--font-display); font-size: 24px; font-weight: 300; line-height: 1.2; }\n.own-elevenlabs .el-orb-card p { position: relative; z-index: 1; font-size: 15px; line-height: 1.5; letter-spacing: .15px; color: var(--body); }\n\n/* ── library rows ──────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-library { padding: var(--section) var(--gut); background: var(--canvas-soft); }\n.own-elevenlabs .el-library-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin-bottom: 28px; }\n.own-elevenlabs .el-search { display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 20px; border-radius: var(--r-pill); background: var(--surface-card); border: 1px solid var(--hairline-strong); min-width: 260px; }\n.own-elevenlabs .el-search svg { width: 18px; height: 18px; color: var(--muted); flex: none; }\n.own-elevenlabs .el-search input { width: 100%; border: 0; background: none; color: var(--ink); font: inherit; font-size: 15px; letter-spacing: .15px; }\n.own-elevenlabs .el-search input:focus { outline: none; }\n.own-elevenlabs .el-voice-list { list-style: none; display: grid; }\n.own-elevenlabs .el-voice { display: grid; grid-template-columns: 44px 1fr auto; align-items: center; gap: 18px; padding: 18px 0; border-top: 1px solid var(--hairline); }\n.own-elevenlabs .el-voice:last-child { border-bottom: 1px solid var(--hairline); }\n.own-elevenlabs .el-voice-ico { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9999px; background: var(--surface-strong); font-size: 12px; font-weight: 600; color: var(--ink); }\n.own-elevenlabs .el-voice-name { display: grid; gap: 2px; }\n.own-elevenlabs .el-voice-name b { font-size: 16px; font-weight: 500; letter-spacing: .18px; }\n.own-elevenlabs .el-voice-name span { font-size: 14px; color: var(--muted); }\n.own-elevenlabs .el-voice-tag { padding: 4px 12px; border-radius: var(--r-pill); background: var(--surface-strong); font-size: 12px; font-weight: 600; letter-spacing: .6px; text-transform: uppercase; color: var(--ink); white-space: nowrap; }\n\n/* ── product stack ──────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-stack-sec { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(28px, 4cqi, 56px); align-items: center; padding: var(--section) var(--gut); }\n.own-elevenlabs .el-stack-sec .el-link { margin-top: 24px; }\n.own-elevenlabs .el-stack { position: relative; height: 320px; }\n.own-elevenlabs .el-stack-card { position: absolute; display: flex; align-items: center; justify-content: space-between; gap: 12px; width: 78%; padding: 22px 26px; border-radius: var(--r-xl); background: var(--surface-card); border: 1px solid var(--hairline); box-shadow: var(--shadow-soft); }\n.own-elevenlabs .el-stack-k { font-size: 15px; color: var(--muted); }\n.own-elevenlabs .el-stack-v { font-family: var(--font-display); font-size: 30px; font-weight: 300; letter-spacing: -0.5px; }\n.own-elevenlabs .el-stack-a { left: 0; top: 0; z-index: 3; }\n.own-elevenlabs .el-stack-b { left: 11%; top: 96px; z-index: 2; }\n.own-elevenlabs .el-stack-c { left: 22%; top: 192px; z-index: 1; }\n\n/* ── testimonials ───────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-quotes { padding: var(--section) var(--gut); background: var(--canvas-soft); }\n.own-elevenlabs .el-quotes-head { text-align: center; margin-bottom: clamp(32px, 5cqi, 48px); }\n.own-elevenlabs .el-quote-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-elevenlabs .el-quote { display: grid; gap: 18px; align-content: start; padding: 32px; border-radius: var(--r-xl); background: var(--surface-card); border: 1px solid var(--hairline); }\n.own-elevenlabs .el-quote p { font-family: var(--font-display); font-size: 20px; font-weight: 300; line-height: 1.4; color: var(--ink); }\n.own-elevenlabs .el-quote-by { display: flex; align-items: center; gap: 12px; font-size: 14px; color: var(--muted); }\n.own-elevenlabs .el-quote-av { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 9999px; background: var(--surface-strong); font-size: 12px; font-weight: 600; color: var(--ink); }\n.own-elevenlabs .el-quote-by b { color: var(--ink); font-weight: 500; }\n\n/* ── pricing ────────────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-pricing { padding: var(--section) var(--gut); }\n.own-elevenlabs .el-pricing-head { text-align: center; max-width: 640px; margin: 0 auto clamp(32px, 5cqi, 48px); }\n.own-elevenlabs .el-tier-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: stretch; }\n.own-elevenlabs .el-tier { display: grid; gap: 12px; align-content: start; padding: 32px; border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--surface-card); }\n.own-elevenlabs .el-tier-name { font-size: 13px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }\n.own-elevenlabs .el-tier-price { font-family: var(--font-display); font-size: clamp(30px, 3.4cqi, 44px); font-weight: 300; line-height: 1.08; letter-spacing: -0.9px; }\n.own-elevenlabs .el-tier-price span { font-family: var(--font-body); font-size: 13px; color: var(--muted); letter-spacing: 0; }\n.own-elevenlabs .el-tier ul { list-style: none; display: grid; gap: 10px; margin: 8px 0 12px; padding-top: 18px; border-top: 1px solid var(--hairline); font-size: 15px; color: var(--body); }\n.own-elevenlabs .el-tier .el-btn { width: 100%; }\n.own-elevenlabs .el-tier-featured { background: var(--surface-dark); border-color: var(--surface-dark); color: var(--on-dark); }\n.own-elevenlabs .el-tier-featured .el-tier-name { color: rgba(255, 255, 255, .6); }\n.own-elevenlabs .el-tier-featured .el-tier-price { color: var(--on-dark); }\n.own-elevenlabs .el-tier-featured ul { border-top-color: rgba(255, 255, 255, .16); color: rgba(255, 255, 255, .78); }\n.own-elevenlabs .el-tier-featured .el-btn-primary { background: var(--canvas); color: var(--ink); }\n\n/* ── CTA band ──────────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-cta { position: relative; overflow: hidden; padding: clamp(64px, 9cqi, 96px) var(--gut); text-align: center; }\n.own-elevenlabs .el-cta-title { position: relative; z-index: 1; font-family: var(--font-display); font-size: clamp(30px, 4.2cqi, 48px); font-weight: 300; line-height: 1.17; letter-spacing: -0.36px; margin-bottom: 26px; }\n.own-elevenlabs .el-cta .el-btn { position: relative; z-index: 1; }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-elevenlabs .el-foot { padding: clamp(48px, 6cqi, 64px) var(--gut) 32px; border-top: 1px solid var(--hairline); }\n.own-elevenlabs .el-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; padding-bottom: 40px; }\n.own-elevenlabs .el-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-elevenlabs .el-foot-col h3 { font-size: 14px; font-weight: 500; color: var(--ink); margin-bottom: 4px; }\n.own-elevenlabs .el-foot-col a { font-size: 15px; color: var(--body); }\n.own-elevenlabs .el-foot-col a:hover { color: var(--ink); }\n.own-elevenlabs .el-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid var(--hairline); font-size: 14px; color: var(--muted); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-elevenlabs .el-menu { display: none; }\n  .own-elevenlabs .el-burger { display: flex; }\n  .own-elevenlabs .el-orb-grid { grid-template-columns: 1fr; }\n  .own-elevenlabs .el-stack-sec { grid-template-columns: 1fr; }\n  .own-elevenlabs .el-quote-grid { grid-template-columns: 1fr; }\n  .own-elevenlabs .el-tier-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-elevenlabs .el-nav { top: 66px; height: 58px; gap: 10px; }\n  .own-elevenlabs .el-wave { flex-wrap: wrap; gap: 14px; }\n  .own-elevenlabs .el-stack { height: auto; display: grid; gap: 14px; }\n  .own-elevenlabs .el-stack-card { position: static; width: 100%; }\n  .own-elevenlabs .el-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-elevenlabs .el-hero-cta { flex-direction: column; align-items: stretch; }\n  .own-elevenlabs .el-library-head { align-items: stretch; }\n  .own-elevenlabs .el-search { min-width: 0; width: 100%; }\n  .own-elevenlabs .el-voice { grid-template-columns: 40px 1fr; row-gap: 8px; }\n  .own-elevenlabs .el-voice-tag { grid-column: 2; justify-self: start; }\n  .own-elevenlabs .el-foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-elevenlabs *, .own-elevenlabs *::before, .own-elevenlabs *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — in ElevenLabs' design language, for showcase.html ══════════
   Registers window.OWN_LAYOUTS['elevenlabs'].init(root). Renders the waveform
   bars, the gradient-orb feature cards, the board library rows and testimonials.
   The only motion is the waveform pulse, which respects prefers-reduced-motion.
   Returns a cleanup that cancels the interval, rAF, and every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var ORBS = ['var(--gradient-mint)', 'var(--gradient-peach)', 'var(--gradient-lavender)', 'var(--gradient-sky)', 'var(--gradient-rose)'];
  var CARDS = [
    { orb: ORBS[0], h: 'Live operations boards', p: 'Throughput, yield, and cost on one calm, reconciled surface.' },
    { orb: ORBS[1], h: 'A semantic layer, plainly written', p: 'Definitions held once and read the same by every desk and every shift.' },
    { orb: ORBS[2], h: 'Digests with editorial polish', p: 'The night shift gets the reconciled board in their own inbox, on their own clock.' }
  ];
  var BOARDS = [
    { ico: 'TP', name: 'Throughput', sub: '6 lines · Luzon', tag: 'Live' },
    { ico: 'YL', name: 'Line yield', sub: '14 lines · all regions', tag: '94.6%' },
    { ico: 'PO', name: 'Port operations', sub: '3 berths · Busan', tag: '98.1%' },
    { ico: 'CU', name: 'Cost per unit', sub: '12 regions', tag: '$2.41' },
    { ico: 'AR', name: 'Anomaly review', sub: 'Across the floor', tag: '3 open' }
  ];
  var QUOTES = [
    { q: '\u201CIt reads like the FT and reconciles like a ledger. The night shift finally trusts the number.\u201D', who: 'Rhea Mercado', role: 'Head of Operations, Caldera', ini: 'RM' },
    { q: '\u201CWe retired three spreadsheets and a nightly batch. The board is the single source now.\u201D', who: 'Dane Ocampo', role: 'Ops Analyst, Portway', ini: 'DO' },
    { q: '\u201CThe digests land before the shift meeting, already reconciled. It changed the cadence of the floor.\u201D', who: 'Mika Navarro', role: 'Plant Lead, Nordvik', ini: 'MN' }
  ];
  var HEIGHTS = [30, 55, 42, 70, 38, 62, 48, 78, 44, 58, 34, 66, 50, 72, 40, 60, 36, 54, 46, 68, 32, 52, 44, 74];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['elevenlabs'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }
      var intervals = [];
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }
      function every(fn, ms) { var id = window.setInterval(fn, ms); intervals.push(id); return id; }
      function $(s) { return root.querySelector(s); }

      /* ── waveform bars ──────────────────────────────────────────────────── */
      var bars = $('#elBars');
      if (bars) {
        bars.innerHTML = HEIGHTS.map(function (h) { return '<i style="--h:' + h + '%"></i>'; }).join('');
      }

      var playing = false;
      var barEls = bars ? bars.querySelectorAll('i') : [];
      function paintBars(mult) {
        Array.prototype.forEach.call(barEls, function (b, i) {
          var base = HEIGHTS[i % HEIGHTS.length];
          var h = Math.max(12, Math.min(100, base * mult));
          b.style.height = h + '%';
        });
      }
      on($('#elPlay'), 'click', function () {
        playing = !playing;
        if (bars) bars.classList.toggle('playing', playing);
        var play = $('#elPlay');
        if (play) play.setAttribute('aria-label', playing ? 'Pause shift digest' : 'Play shift digest');
        if (!playing) { paintBars(1); }
      });
      if (!reduced && barEls.length) {
        var phase = 0;
        every(function () {
          if (!playing) return;
          phase += 0.6;
          Array.prototype.forEach.call(barEls, function (b, i) {
            var base = HEIGHTS[i % HEIGHTS.length] / 100;
            var h = 20 + Math.abs(Math.sin(phase + i * 0.5)) * 80 * base + 10;
            b.style.height = Math.min(100, h) + '%';
          });
        }, 120);
      }

      /* ── orb feature cards ─────────────────────────────────────────────── */
      var orbGrid = $('#elOrbGrid');
      if (orbGrid) {
        orbGrid.innerHTML = CARDS.map(function (c) {
          return '<article class="el-orb-card">'
            + '<span class="el-card-orb" style="background:radial-gradient(circle,' + c.orb + ',transparent 70%)" aria-hidden="true"></span>'
            + '<h3>' + esc(c.h) + '</h3>'
            + '<p>' + esc(c.p) + '</p>'
            + '</article>';
        }).join('');
      }

      /* ── board library rows ─────────────────────────────────────────────── */
      var list = $('#elVoiceList');
      if (list) {
        list.innerHTML = BOARDS.map(function (b) {
          return '<li class="el-voice">'
            + '<span class="el-voice-ico" aria-hidden="true">' + esc(b.ico) + '</span>'
            + '<span class="el-voice-name"><b>' + esc(b.name) + '</b><span>' + esc(b.sub) + '</span></span>'
            + '<span class="el-voice-tag">' + esc(b.tag) + '</span>'
            + '</li>';
        }).join('');
      }

      /* ── testimonials ───────────────────────────────────────────────────── */
      var qGrid = $('#elQuoteGrid');
      if (qGrid) {
        qGrid.innerHTML = QUOTES.map(function (t) {
          return '<figure class="el-quote">'
            + '<p>' + t.q + '</p>'
            + '<figcaption class="el-quote-by"><span class="el-quote-av" aria-hidden="true">' + esc(t.ini) + '</span><span><b>' + esc(t.who) + '</b><br>' + esc(t.role) + '</span></figcaption>'
            + '</figure>';
        }).join('');
      }

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        intervals.forEach(function (id) { clearInterval(id); });
      };
    }
  };
})();
